-- CreateTable
CREATE TABLE "ServicePriceItem" (
    "id" TEXT NOT NULL,
    "serviceId" TEXT NOT NULL,
    "code" TEXT,
    "name" TEXT NOT NULL,
    "price" DECIMAL(12,2),
    "currency" TEXT NOT NULL DEFAULT 'AZN',
    "note" TEXT,
    "active" BOOLEAN NOT NULL DEFAULT true,
    "sortOrder" INTEGER NOT NULL DEFAULT 0,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" TIMESTAMP(3) NOT NULL,
    CONSTRAINT "ServicePriceItem_pkey" PRIMARY KEY ("id")
);

CREATE INDEX "ServicePriceItem_serviceId_active_sortOrder_idx" ON "ServicePriceItem"("serviceId", "active", "sortOrder");
CREATE INDEX "ServicePriceItem_name_idx" ON "ServicePriceItem"("name");
ALTER TABLE "ServicePriceItem" ADD CONSTRAINT "ServicePriceItem_serviceId_fkey" FOREIGN KEY ("serviceId") REFERENCES "Service"("id") ON DELETE CASCADE ON UPDATE CASCADE;

