  ('e77cc449-644d-4cc9-8e1d-a7fd9e284e8f', 'psixiatriya', 'Psixiatriya', 'Psixi sağlamlıq üzrə konsultasiya və müayinə xidmətləri.', 'Psixi sağlamlığın qiymətləndirilməsi və fərdi konsultasiya xidmətləri.', ARRAY[]::TEXT[], ARRAY[]::TEXT[], true, false, 10, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
