  ('9a5ee440-faca-4a8f-8b99-9d6af4f1ad62', 'laboratoriya', 'Laboratoriya', 'Klinik və instrumental laborator müayinələrin geniş spektri.', 'Müasir laborator diaqnostika, skrininq və monitorinq xidmətləri.', ARRAY[]::TEXT[], ARRAY[]::TEXT[], true, false, 12, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
  ('95c9532d-9e9d-493f-89c0-f7e007837e23', 'poliklinika-ve-reabilitasiya', 'Poliklinika və reabilitasiya', 'Fizioterapiya və ambulator manipulyasiya xidmətləri.', 'Bərpa, fizioterapiya və gündəlik ambulator prosedurlar üçün koordinasiyalı xidmət.', ARRAY[]::TEXT[], ARRAY[]::TEXT[], true, false, 13, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
